#!/usr/bin/env python3
# Build _ssp_freeze_v2.json from _ssp_freeze.json per reconciliation of the three adversarial critiques.
import json, collections

BASE = "/tmp/claude-0/-home-user-THE-LEGAL-WATCHTOWER/8a568901-aaa2-51c4-86b4-eb7bbdff4e90/scratchpad"
